/* Direito Processual Penal — 10 itens inéditos por subtópico do Edital PRF nº 1/2021 (5 C + 5 E cada). */
(function () {
  var D = 'Direito Processual Penal', n = 0;
  function q(topico, tema, gabarito, enunciado, comentario) {
    n++;
    return { id: 'DPP-' + String(n).padStart(3, '0'), disciplina: D, tema: tema, topico: topico,
             gabarito: gabarito, enunciado: enunciado, comentario: comentario };
  }
  var AP = 'Ação penal', TCO = 'TCO e atos processuais', PR = 'Prova', PS = 'Prisão', ID = 'Identificação e diligências';
  var T11 = '1.1 Ação penal: conceito';
  var T12 = '1.2 Ação penal: características';
  var T13 = '1.3 Ação penal: espécies';
  var T14 = '1.4 Ação penal: condições';
  var T2 = '2 Termo Circunstanciado de Ocorrência (Lei 9.099/1995)';
  var T21 = '2.1 Atos processuais: forma, lugar e tempo';
  var T31 = '3.1 Prova: conceito, objeto e classificação';
  var T32 = '3.2 Preservação de local de crime';
  var T33 = '3.3 Requisitos e ônus da prova';
  var T34 = '3.4 Provas ilícitas';
  var T35 = '3.5 Meios de prova';
  var T36 = '3.6 Busca e apreensão';
  var T41 = '4.1 Prisão: conceito, formalidades, espécies e mandado';
  var T42 = '4.2 Prisão em flagrante';
  var T5 = '5 Identificação criminal (CF art. 5º, LVIII, e Lei 12.037/2009, art. 3º)';
  var T6 = '6 Diligências investigatórias (arts. 6º e 13 do CPP)';
  window.QUESTOES = (window.QUESTOES || []).concat([
    /* 1.1 Ação penal: conceito */
    q(T11, AP, 'C', 'A ação penal pode ser conceituada como o direito público subjetivo de exigir do Estado-juiz a aplicação do direito penal objetivo a um caso concreto, sendo esse direito autônomo em relação ao direito material discutido.', 'Correto. A doutrina define a ação penal como direito público subjetivo, autônomo e abstrato de provocar a jurisdição para a aplicação do direito penal ao caso concreto.'),
    q(T11, AP, 'E', 'Por ser abstrato, o direito de ação penal somente existe quando a sentença final reconhece a procedência da pretensão punitiva deduzida pelo acusador.', 'Errado. A abstração significa justamente que o direito de ação existe independentemente do resultado do processo; a sentença absolutória não elimina o exercício regular do direito de ação.'),
    q(T11, AP, 'C', 'Segundo o Código Penal, a ação penal é pública, salvo quando a lei expressamente a declara privativa do ofendido.', 'Correto. É a redação do art. 100, caput, do CP: a regra é a ação penal pública; a privada depende de previsão legal expressa.'),
    q(T11, AP, 'E', 'Se a lei penal for omissa quanto à espécie de ação penal cabível para determinado crime, presume-se que a ação seja privada, dependendo de queixa do ofendido.', 'Errado. No silêncio da lei, a ação penal é pública incondicionada (art. 100 do CP); a ação privada e a condicionada exigem previsão expressa.'),
    q(T11, AP, 'C', 'A Constituição Federal atribui ao Ministério Público, como função institucional, promover, privativamente, a ação penal pública, na forma da lei.', 'Correto. É o que dispõe o art. 129, I, da CF, que consagra a titularidade privativa do MP na ação penal pública.'),
    q(T11, AP, 'E', 'Policial rodoviário federal que efetua a prisão em flagrante do autor de crime de ação penal pública incondicionada pode, ao lavrar a ocorrência, dar início à ação penal, que posteriormente é assumida pelo Ministério Público.', 'Errado. O procedimento judicialiforme não foi recepcionado pela CF/1988: a ação penal pública é promovida privativamente pelo MP (art. 129, I, da CF), mediante denúncia.'),
    q(T11, AP, 'C', 'Na ação penal privada, o Estado transfere ao ofendido a legitimidade para promover a ação em juízo, mas conserva para si a titularidade do direito de punir.', 'Correto. Na ação privada há substituição processual: o ofendido age em nome próprio na defesa de interesse alheio, pois o jus puniendi continua sendo do Estado.'),
    q(T11, AP, 'E', 'Na ação penal privada, o direito de punir passa a pertencer ao ofendido, que o exerce como titular por meio da queixa-crime.', 'Errado. O jus puniendi é sempre estatal; ao ofendido é conferida apenas a legitimidade para agir (jus persequendi in judicio), em regime de substituição processual.'),
    q(T11, AP, 'C', 'A peça inaugural da ação penal pública é a denúncia, ao passo que a ação penal privada se inicia por meio de queixa-crime.', 'Correto. Arts. 24, 30 e 41 do CPP: a ação pública é promovida por denúncia do MP e a privada, por queixa do ofendido ou de seu representante legal.'),
    q(T11, AP, 'E', 'O inquérito policial é a peça inaugural da ação penal pública, de modo que sua instauração já marca o início do exercício do direito de ação.', 'Errado. O inquérito é procedimento administrativo, pré-processual e dispensável (arts. 12 e 39, § 5º, do CPP); a ação penal pública inicia-se com a denúncia.'),

    /* 1.2 Ação penal: características */
    q(T12, AP, 'C', 'Pelo princípio da obrigatoriedade, presentes indícios de autoria e prova da materialidade de crime de ação penal pública, o Ministério Público deve oferecer denúncia, não lhe cabendo juízo de conveniência política, ressalvadas as mitigações previstas em lei.', 'Correto. A obrigatoriedade (legalidade processual) rege a ação pública; mitigações legais, como a transação penal e o acordo de não persecução penal, não afastam a regra.'),
    q(T12, AP, 'E', 'Pelo princípio da indisponibilidade, o Ministério Público, depois de oferecida a denúncia, pode dela desistir caso se convença, durante a instrução, de que as provas são frágeis.', 'Errado. Segundo o art. 42 do CPP, o MP não poderá desistir da ação penal; poderá, quando muito, requerer a absolvição ao final.'),
    q(T12, AP, 'C', 'Em decorrência da indisponibilidade da ação penal pública, o Ministério Público não pode desistir de recurso que haja interposto.', 'Correto. É a regra do art. 576 do CPP, desdobramento da indisponibilidade prevista no art. 42.'),
    q(T12, AP, 'E', 'A ação penal privada é regida pelo princípio da obrigatoriedade, de modo que o ofendido, ciente da autoria, está obrigado a oferecer queixa no prazo de seis meses.', 'Errado. A ação privada rege-se pela oportunidade ou conveniência: o ofendido decide se oferece ou não a queixa, podendo deixar transcorrer o prazo decadencial.'),
    q(T12, AP, 'C', 'Na ação penal privada, a queixa contra qualquer dos autores do crime obrigará ao processo de todos, cabendo ao Ministério Público velar pela sua indivisibilidade.', 'Correto. É a literalidade do art. 48 do CPP, que consagra a indivisibilidade da ação penal privada.'),
    q(T12, AP, 'E', 'Na ação penal privada, a renúncia ao direito de queixa em relação a um dos autores do crime não alcança os demais, que continuam sujeitos à persecução.', 'Errado. Pelo art. 49 do CPP, a renúncia ao exercício do direito de queixa em relação a um dos autores do crime a todos se estenderá.'),
    q(T12, AP, 'C', 'A transação penal prevista na Lei 9.099/1995 e o acordo de não persecução penal previsto no art. 28-A do CPP são apontados pela doutrina como mitigações ao princípio da obrigatoriedade da ação penal pública.', 'Correto. Em ambos os casos, o MP, mesmo dispondo de justa causa, pode deixar de oferecer denúncia mediante solução consensual autorizada em lei (art. 76 da Lei 9.099/1995 e art. 28-A do CPP).'),
    q(T12, AP, 'E', 'Na ação penal privada, o perdão concedido pelo ofendido a um dos querelados aproveita a todos, produzindo efeito inclusive em relação ao querelado que o recusar.', 'Errado. Conforme o art. 51 do CPP, o perdão concedido a um dos querelados aproveita a todos, mas não produz efeito quanto ao que o recusar, por ser ato bilateral.'),
    q(T12, AP, 'C', 'Em razão da intranscendência, a ação penal somente pode ser proposta contra quem se atribui a autoria ou a participação no crime, não podendo ser dirigida, por exemplo, contra os herdeiros do suposto autor.', 'Correto. A intranscendência decorre do art. 5º, XLV, da CF (a pena não passará da pessoa do condenado), limitando o polo passivo da ação penal aos supostos autores e partícipes.'),
    q(T12, AP, 'E', 'O princípio da oficialidade significa que a ação penal privada deve ser promovida por órgão oficial do Estado, atuando o ofendido apenas como assistente.', 'Errado. A oficialidade caracteriza a ação penal pública, promovida por órgão oficial (MP); na ação privada, a iniciativa é do ofendido, por meio de queixa.'),

    /* 1.3 Ação penal: espécies */
    q(T13, AP, 'C', 'A ação penal pública condicionada pode depender, conforme a previsão legal, de representação do ofendido ou de requisição do Ministro da Justiça.', 'Correto. É o que estabelece o art. 24 do CPP, que prevê essas duas condições de procedibilidade para a ação penal pública condicionada.'),
    q(T13, AP, 'E', 'Mesmo depois de oferecida a denúncia, a representação do ofendido poderá ser retratada até a prolação da sentença, o que impede o prosseguimento da ação penal.', 'Errado. Conforme o art. 25 do CPP e o art. 102 do CP, a representação é irretratável depois de oferecida a denúncia.'),
    q(T13, AP, 'C', 'Admite-se ação penal privada nos crimes de ação pública se esta não for intentada pelo Ministério Público no prazo legal.', 'Correto. É a ação penal privada subsidiária da pública, prevista no art. 5º, LIX, da CF e no art. 29 do CPP.'),
    q(T13, AP, 'E', 'Cabe ação penal privada subsidiária da pública quando o Ministério Público, após analisar o inquérito, determina fundamentadamente o seu arquivamento.', 'Errado. A ação privada subsidiária pressupõe inércia do MP no prazo legal; não cabe quando o MP atua, ainda que seja para promover o arquivamento.'),
    q(T13, AP, 'C', 'Na ação penal privada subsidiária da pública, o Ministério Público pode aditar a queixa, repudiá-la e oferecer denúncia substitutiva e, em caso de negligência do querelante, retomar a ação como parte principal.', 'Correto. São as prerrogativas previstas no art. 29 do CPP, que preservam a titularidade originária do MP.'),
    q(T13, AP, 'E', 'O crime de lesão corporal leve praticado contra mulher no âmbito de violência doméstica e familiar é processado mediante ação penal pública condicionada à representação da vítima.', 'Errado. Segundo a Súmula 542 do STJ, a ação penal relativa ao crime de lesão corporal resultante de violência doméstica contra a mulher é pública incondicionada.'),
    q(T13, AP, 'C', 'Na ação penal privada personalíssima, como no crime de induzimento a erro essencial e ocultação de impedimento ao casamento, a queixa só pode ser oferecida pelo próprio ofendido, não se transmitindo o direito a sucessores em caso de morte.', 'Correto. No caso do art. 236 do CP, a ação depende de queixa do contraente enganado, e o direito não se transmite ao cônjuge, ascendente, descendente ou irmão.'),
    q(T13, AP, 'E', 'Nos crimes de ação penal privada, o direito de queixa extingue-se com a morte do ofendido, independentemente da espécie de ação privada envolvida.', 'Errado. Na ação privada exclusiva, morto o ofendido, o direito de queixa passa ao cônjuge, ascendente, descendente ou irmão (art. 31 do CPP); a intransmissibilidade é própria da ação personalíssima.'),
    q(T13, AP, 'C', 'Desde a Lei 13.718/2018, os crimes contra a liberdade sexual e os crimes sexuais contra vulnerável são processados mediante ação penal pública incondicionada.', 'Correto. É a redação atual do art. 225 do CP, que deixou de exigir representação da vítima nesses crimes.'),
    q(T13, AP, 'E', 'Com o Pacote Anticrime, o crime de estelionato passou a ser, em regra, de ação penal pública incondicionada.', 'Errado. O Pacote Anticrime incluiu o § 5º no art. 171 do CP, tornando o estelionato, em regra, crime de ação pública condicionada à representação, com exceções (ex.: vítima for a administração pública ou maior de 70 anos).'),

    /* 1.4 Ação penal: condições */
    q(T14, AP, 'C', 'A denúncia ou queixa será rejeitada quando for manifestamente inepta, quando faltar pressuposto processual ou condição para o exercício da ação penal, ou quando faltar justa causa.', 'Correto. São as hipóteses de rejeição da peça acusatória previstas no art. 395, I a III, do CPP.'),
    q(T14, AP, 'E', 'Na ação penal pública incondicionada, a legitimidade ativa é concorrente entre o Ministério Público e a vítima, que pode oferecer denúncia independentemente de inércia do órgão ministerial.', 'Errado. A legitimidade é privativa do MP (art. 129, I, da CF); a vítima só pode agir por meio de queixa subsidiária, se houver inércia ministerial (art. 29 do CPP).'),
    q(T14, AP, 'C', 'A justa causa para a ação penal corresponde à existência de lastro probatório mínimo, consistente em prova da materialidade e indícios suficientes de autoria.', 'Correto. A ausência de justa causa conduz à rejeição da denúncia ou queixa, nos termos do art. 395, III, do CPP.'),
    q(T14, AP, 'E', 'A representação do ofendido exige forma sacramental, de modo que, sem termo formal com essa denominação, não se considera satisfeita a condição de procedibilidade.', 'Errado. A jurisprudência dispensa formalismo: basta a manifestação inequívoca da vontade da vítima de ver o autor processado, como o registro da ocorrência perante a autoridade policial.'),
    q(T14, AP, 'C', 'Nos crimes em que a ação penal pública depender de representação, o inquérito policial não poderá sem ela ser iniciado.', 'Correto. É a regra do art. 5º, § 4º, do CPP: a representação é condição de procedibilidade também para a instauração do inquérito.'),
    q(T14, AP, 'E', 'O direito de representação deve ser exercido no prazo de seis meses contados da data do fato, independentemente do momento em que o ofendido tenha descoberto a autoria.', 'Errado. Pelo art. 38 do CPP, o prazo decadencial de seis meses conta-se, em regra, do dia em que o ofendido vier a saber quem é o autor do crime.'),
    q(T14, AP, 'C', 'Nos crimes cuja ação penal depende de requisição do Ministro da Justiça, essa requisição, embora seja condição de procedibilidade, não vincula o Ministério Público, que pode deixar de oferecer denúncia se entender ausente justa causa.', 'Correto. A doutrina majoritária entende que a requisição apenas autoriza a atuação do MP, que mantém sua independência funcional para formar a opinio delicti.'),
    q(T14, AP, 'E', 'Na ação penal privada, a legitimidade ativa pertence ao Ministério Público, que atua como substituto processual do ofendido.', 'Errado. Na ação privada, o legitimado ativo é o ofendido ou quem tenha qualidade para representá-lo (art. 30 do CPP); o MP atua como fiscal da ordem jurídica.'),
    q(T14, AP, 'C', 'A representação pode ser exercida pessoalmente ou por procurador com poderes especiais, mediante declaração escrita ou oral, feita ao juiz, ao órgão do Ministério Público ou à autoridade policial.', 'Correto. É a disciplina do art. 39 do CPP.'),
    q(T14, AP, 'E', 'A requisição do Ministro da Justiça submete-se ao prazo decadencial de seis meses, contado do dia em que se tomar conhecimento da autoria do crime.', 'Errado. A lei não fixa prazo decadencial para a requisição do Ministro da Justiça; o art. 38 do CPP refere-se à queixa e à representação, de modo que a requisição pode ser feita enquanto não extinta a punibilidade.'),

    /* 2 Termo Circunstanciado de Ocorrência */
    q(T2, TCO, 'C', 'Consideram-se infrações penais de menor potencial ofensivo as contravenções penais e os crimes a que a lei comine pena máxima não superior a dois anos, cumulada ou não com multa.', 'Correto. É a definição do art. 61 da Lei 9.099/1995.'),
    q(T2, TCO, 'E', 'Considera-se de menor potencial ofensivo todo crime cuja pena mínima cominada seja igual ou inferior a um ano.', 'Errado. O critério é a pena máxima não superior a dois anos (art. 61 da Lei 9.099/1995); a pena mínima de até um ano é requisito da suspensão condicional do processo (art. 89).'),
    q(T2, TCO, 'C', 'A autoridade policial que tomar conhecimento de infração de menor potencial ofensivo lavrará termo circunstanciado e o encaminhará imediatamente ao Juizado, com o autor do fato e a vítima, providenciando-se as requisições dos exames periciais necessários.', 'Correto. É a literalidade do art. 69, caput, da Lei 9.099/1995.'),
    q(T2, TCO, 'E', 'O autor de infração de menor potencial ofensivo que, após a lavratura do termo circunstanciado, assume o compromisso de comparecer ao Juizado deve, ainda assim, ser autuado em flagrante, sendo-lhe concedida fiança.', 'Errado. Segundo o art. 69, parágrafo único, da Lei 9.099/1995, nesse caso não se imporá prisão em flagrante nem se exigirá fiança.'),
    q(T2, TCO, 'C', 'Em fiscalização em rodovia federal, condutor flagrado dirigindo sem habilitação e gerando perigo de dano (art. 309 do CTB, pena de detenção de seis meses a um ano, ou multa) pratica infração de menor potencial ofensivo, sendo cabível a lavratura de termo circunstanciado.', 'Correto. A pena máxima não supera dois anos (art. 61 da Lei 9.099/1995), de modo que o procedimento é o do termo circunstanciado, nos termos do art. 69.'),
    q(T2, TCO, 'E', 'Condutor flagrado em rodovia federal com capacidade psicomotora alterada em razão de álcool (art. 306 do CTB, pena de detenção de seis meses a três anos) pratica infração de menor potencial ofensivo, devendo ser lavrado termo circunstanciado.', 'Errado. A pena máxima do art. 306 do CTB é de três anos, superior ao limite de dois anos do art. 61 da Lei 9.099/1995; não se trata de infração de menor potencial ofensivo.'),
    q(T2, TCO, 'C', 'O STF já assentou que o termo circunstanciado não constitui procedimento investigativo, mas peça informativa com a descrição dos fatos, de modo que sua lavratura não é atividade exclusiva da polícia judiciária.', 'Correto. Esse entendimento foi firmado pelo STF (ADI 3.807, entre outros julgados), reconhecendo que o termo circunstanciado não é ato de investigação privativo de delegado de polícia.'),
    q(T2, TCO, 'E', 'Nos crimes praticados com violência doméstica e familiar contra a mulher cuja pena máxima não exceda dois anos, aplica-se o rito da Lei 9.099/1995, com lavratura de termo circunstanciado e possibilidade de transação penal.', 'Errado. O art. 41 da Lei 11.340/2006 afasta a aplicação da Lei 9.099/1995 aos crimes praticados com violência doméstica e familiar contra a mulher, independentemente da pena prevista.'),
    q(T2, TCO, 'C', 'No caso de porte de droga para consumo pessoal (art. 28 da Lei 11.343/2006), não se imporá prisão em flagrante, devendo o autor ser encaminhado ao juízo competente ou assumir o compromisso de a ele comparecer, lavrando-se termo circunstanciado.', 'Correto. É o que prevê o art. 48, § 2º, da Lei 11.343/2006.'),
    q(T2, TCO, 'E', 'O termo circunstanciado deve conter apuração exaustiva dos fatos, com indiciamento formal do autor e oitiva de todas as testemunhas sob compromisso, à semelhança do inquérito policial.', 'Errado. O termo circunstanciado é peça simplificada, orientada pelos critérios de oralidade, informalidade, economia processual e celeridade (art. 62 da Lei 9.099/1995), sem indiciamento.'),

    /* 2.1 Atos processuais: forma, lugar e tempo */
    q(T21, TCO, 'C', 'As audiências, sessões e atos processuais serão, em regra, públicos, mas, se da publicidade puder resultar escândalo, inconveniente grave ou perigo de perturbação da ordem, o juiz poderá determinar que o ato seja realizado a portas fechadas.', 'Correto. É a disciplina do art. 792, caput e § 1º, do CPP.'),
    q(T21, TCO, 'E', 'No processo penal, os prazos são interrompidos por férias, domingos e feriados, recomeçando a correr por inteiro no primeiro dia útil seguinte.', 'Errado. Segundo o art. 798 do CPP, os prazos são contínuos e peremptórios, não se interrompendo por férias, domingo ou dia feriado.'),
    q(T21, TCO, 'C', 'Na contagem dos prazos processuais penais, não se computa o dia do começo, incluindo-se, porém, o do vencimento.', 'Correto. É a regra do art. 798, § 1º, do CPP.'),
    q(T21, TCO, 'E', 'No processo penal, os prazos contam-se da data da juntada aos autos do mandado ou da carta precatória, e não da data da intimação.', 'Errado. Conforme a Súmula 710 do STF, no processo penal contam-se os prazos da data da intimação, e não da juntada aos autos do mandado ou da carta precatória ou de ordem.'),
    q(T21, TCO, 'C', 'O prazo processual penal que terminar em domingo ou dia feriado considera-se prorrogado até o dia útil imediato.', 'Correto. É a previsão do art. 798, § 3º, do CPP.'),
    q(T21, TCO, 'E', 'As sessões de julgamento podem ser marcadas para domingos e feriados, ao passo que os demais atos do processo não podem ser praticados nesses dias.', 'Errado. O art. 797 do CPP dispõe o inverso: excetuadas as sessões de julgamento, que não serão marcadas para domingo ou feriado, os demais atos poderão ser praticados em férias, domingos e feriados.'),
    q(T21, TCO, 'C', 'Se a intimação ocorrer em uma sexta-feira, ou a publicação com efeito de intimação for feita nesse dia, o prazo judicial terá início na segunda-feira imediata, salvo se não houver expediente, caso em que começará no primeiro dia útil que se seguir.', 'Correto. É o teor da Súmula 310 do STF.'),
    q(T21, TCO, 'E', 'A prisão somente pode ser efetuada em dias úteis e no horário do expediente forense, sob pena de nulidade.', 'Errado. Segundo o art. 283, § 2º, do CPP, a prisão poderá ser efetuada em qualquer dia e a qualquer hora, respeitadas as restrições relativas à inviolabilidade do domicílio.'),
    q(T21, TCO, 'C', 'No âmbito dos Juizados Especiais Criminais, os atos processuais serão públicos e poderão realizar-se em horário noturno e em qualquer dia da semana, conforme dispuserem as normas de organização judiciária.', 'Correto. É o que prevê o art. 64 da Lei 9.099/1995.'),
    q(T21, TCO, 'E', 'A suspensão do curso dos prazos processuais penais entre 20 de dezembro e 20 de janeiro aplica-se inclusive aos processos que envolvam réus presos.', 'Errado. O art. 798-A do CPP excetua da suspensão os casos que envolvam réus presos, nos processos vinculados a essas prisões, além dos procedimentos da Lei Maria da Penha e das medidas urgentes.'),

    /* 3.1 Prova: conceito, objeto e classificação */
    q(T31, PR, 'C', 'Os fatos notórios, de conhecimento geral no meio social, independem de prova no processo penal.', 'Correto. A doutrina aponta que fatos notórios, axiomáticos, inúteis e as presunções legais absolutas não constituem objeto de prova.'),
    q(T31, PR, 'E', 'No processo penal, o fato admitido como verdadeiro por ambas as partes dispensa prova, aplicando-se integralmente a regra do processo civil relativa aos fatos incontroversos.', 'Errado. No processo penal, mesmo a confissão tem valor relativo e deve ser confrontada com as demais provas (art. 197 do CPP); fatos incontroversos ainda podem e devem ser provados.'),
    q(T31, PR, 'C', 'Considera-se indício a circunstância conhecida e provada que, tendo relação com o fato, autorize, por indução, concluir-se a existência de outra ou outras circunstâncias.', 'Correto. É a definição do art. 239 do CPP; o indício é classificado como prova indireta.'),
    q(T31, PR, 'E', 'Prova direta é aquela que demonstra uma circunstância da qual se infere, por raciocínio indutivo, a ocorrência do fato principal.', 'Errado. Essa é a definição de prova indireta (como o indício do art. 239 do CPP); a prova direta demonstra o próprio fato a ser provado.'),
    q(T31, PR, 'C', 'O juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar sua decisão exclusivamente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.', 'Correto. É a redação do art. 155, caput, do CPP, que consagra o sistema da persuasão racional.'),
    q(T31, PR, 'E', 'O CPP adota, como regra, o sistema da prova tarifada, no qual cada meio de prova tem valor previamente fixado em lei, vinculando o juiz.', 'Errado. A regra é o sistema do livre convencimento motivado ou persuasão racional (art. 155 do CPP); a íntima convicção vigora excepcionalmente no Tribunal do Júri.'),
    q(T31, PR, 'C', 'Quanto ao sujeito, o depoimento de uma testemunha classifica-se como prova pessoal, ao passo que a arma apreendida com o autor do crime é exemplo de prova real.', 'Correto. Prova pessoal é a que emana de afirmação consciente de uma pessoa; prova real é a que resulta de vestígios deixados em coisas.'),
    q(T31, PR, 'E', 'No processo penal, o direito federal deve ser provado pela parte que o alega, sob pena de não ser considerado pelo juiz.', 'Errado. O juiz conhece o direito federal (iura novit curia); apenas o direito estadual, municipal, estrangeiro ou consuetudinário pode ter seu teor e vigência exigidos da parte.'),
    q(T31, PR, 'C', 'Quanto ao estado das pessoas, a prova no processo penal observa as restrições estabelecidas na lei civil, como ocorre na comprovação da menoridade do réu, que exige documento hábil.', 'Correto. É a regra do art. 155, parágrafo único, do CPP; a Súmula 74 do STJ exige prova por documento hábil para reconhecimento da menoridade.'),
    q(T31, PR, 'E', 'Os elementos informativos colhidos no inquérito policial, por serem produzidos por autoridade estatal, têm o mesmo valor probatório das provas produzidas sob contraditório judicial.', 'Errado. O art. 155 do CPP veda a condenação fundada exclusivamente em elementos informativos da investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.'),

    /* 3.2 Preservação de local de crime */
    q(T32, PR, 'C', 'Logo que tiver conhecimento da prática da infração penal, a autoridade policial deverá dirigir-se ao local, providenciando para que não se alterem o estado e a conservação das coisas até a chegada dos peritos criminais.', 'Correto. É a literalidade do art. 6º, I, do CPP.'),
    q(T32, PR, 'E', 'Policial que chega primeiro a local de crime isolado pode nele ingressar e remover vestígios antes da liberação pelo perito, desde que tenha atribuição policial.', 'Errado. O art. 158-C, § 2º, do CPP proíbe a entrada em locais isolados e a remoção de vestígios antes da liberação pelo perito responsável, tipificando a conduta como fraude processual.'),
    q(T32, PR, 'C', 'O início da cadeia de custódia dá-se com a preservação do local de crime ou com procedimentos policiais ou periciais nos quais seja detectada a existência de vestígio.', 'Correto. É o que dispõe o art. 158-A, § 1º, do CPP.'),
    q(T32, PR, 'E', 'O agente público que reconhece um elemento como de potencial interesse para a prova pericial não tem responsabilidade por sua preservação, a qual incumbe exclusivamente ao perito oficial.', 'Errado. Segundo o art. 158-A, § 2º, do CPP, o agente público que reconhecer o elemento como de potencial interesse fica responsável por sua preservação.'),
    q(T32, PR, 'C', 'Em caso de acidente de trânsito, o policial que primeiro tomar conhecimento do fato poderá autorizar, independentemente de exame do local, a imediata remoção das vítimas e dos veículos que estejam no leito da via e prejudiquem o tráfego, devendo lavrar boletim da ocorrência.', 'Correto. É a regra da Lei 5.970/1973, que exige que o boletim registre o fato, as testemunhas e as demais circunstâncias necessárias ao esclarecimento da verdade.'),
    q(T32, PR, 'E', 'Em acidente de trânsito com vítima em rodovia federal, os veículos envolvidos devem obrigatoriamente permanecer no leito da via até a chegada da perícia, ainda que prejudiquem o tráfego, sendo vedada qualquer remoção sem autorização do perito.', 'Errado. A Lei 5.970/1973 permite que a autoridade ou o agente policial autorize a remoção das vítimas e dos veículos que prejudiquem o tráfego, independentemente de exame do local.'),
    q(T32, PR, 'C', 'O isolamento, etapa da cadeia de custódia, consiste no ato de evitar que se altere o estado das coisas, devendo-se isolar e preservar o ambiente imediato, mediato e relacionado aos vestígios e ao local de crime.', 'Correto. É a definição do art. 158-B, II, do CPP.'),
    q(T32, PR, 'E', 'A coleta dos vestígios em local de crime deve ser realizada obrigatoriamente pelo primeiro policial que chegar ao local, cabendo ao perito apenas a análise posterior.', 'Errado. Segundo o art. 158-C do CPP, a coleta deve ser realizada preferencialmente por perito oficial, que dará o encaminhamento à central de custódia.'),
    q(T32, PR, 'C', 'Os peritos registrarão no laudo as alterações do estado das coisas no local do crime e discutirão, no relatório, as consequências dessas alterações na dinâmica dos fatos.', 'Correto. É o que prevê o art. 169, parágrafo único, do CPP.'),
    q(T32, PR, 'E', 'Para fins de cadeia de custódia, vestígio é apenas o objeto visível a olho nu recolhido no local do crime, não abrangendo materiais latentes.', 'Errado. O art. 158-A, § 3º, do CPP define vestígio como todo objeto ou material bruto, visível ou latente, constatado ou recolhido, que se relaciona à infração penal.'),

    /* 3.3 Requisitos e ônus da prova */
    q(T33, PR, 'C', 'No processo penal, a prova da alegação incumbe a quem a fizer.', 'Correto. É a regra geral do art. 156, caput, do CPP.'),
    q(T33, PR, 'E', 'Em razão da presunção de inocência, cabe ao réu demonstrar que não praticou o crime que lhe é imputado, sob pena de condenação.', 'Errado. A presunção de inocência (art. 5º, LVII, da CF) atribui à acusação o ônus de provar a autoria e a materialidade; o réu não precisa provar sua inocência.'),
    q(T33, PR, 'C', 'O juiz absolverá o réu quando existirem circunstâncias que excluam o crime ou isentem o réu de pena, ou mesmo se houver fundada dúvida sobre sua existência.', 'Correto. É a redação do art. 386, VI, do CPP: a fundada dúvida sobre excludente favorece o réu.'),
    q(T33, PR, 'E', 'Encerrada a instrução com dúvida razoável sobre a autoria, o juiz deve condenar o réu, pois na dúvida prevalece o interesse da sociedade.', 'Errado. Vigora o in dubio pro reo: não existindo prova suficiente para a condenação, o juiz absolverá o réu (art. 386, VII, do CPP).'),
    q(T33, PR, 'C', 'Na audiência de instrução, o juiz pode indeferir as provas consideradas irrelevantes, impertinentes ou protelatórias.', 'Correto. É o que autoriza o art. 400, § 1º, do CPP.'),
    q(T33, PR, 'E', 'O juiz pode ordenar a produção antecipada de provas consideradas urgentes e relevantes sem necessidade de observar a necessidade, a adequação e a proporcionalidade da medida.', 'Errado. O art. 156, I, do CPP exige expressamente a observância da necessidade, adequação e proporcionalidade da medida.'),
    q(T33, PR, 'C', 'O juiz pode determinar, no curso da instrução ou antes de proferir sentença, a realização de diligências para dirimir dúvida sobre ponto relevante.', 'Correto. É a previsão do art. 156, II, do CPP.'),
    q(T33, PR, 'E', 'No processo penal, a acusação está dispensada de provar o dolo do agente, que se presume a partir da comprovação da materialidade do crime.', 'Errado. O dolo integra a imputação e deve ser provado pela acusação (art. 156 do CPP); não há presunção de dolo em desfavor do réu.'),
    q(T33, PR, 'C', 'O CPP estabelece que o processo penal terá estrutura acusatória, vedadas a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação.', 'Correto. É a redação do art. 3º-A do CPP, incluído pelo Pacote Anticrime.'),
    q(T33, PR, 'E', 'A prova emprestada é inadmissível no processo penal em qualquer hipótese, ainda que submetida a contraditório no processo de destino.', 'Errado. A jurisprudência do STF e do STJ admite a prova emprestada, desde que assegurado o contraditório sobre ela no processo em que for utilizada.'),

    /* 3.4 Provas ilícitas */
    q(T34, PR, 'C', 'São inadmissíveis, devendo ser desentranhadas do processo, as provas ilícitas, assim entendidas as obtidas em violação a normas constitucionais ou legais.', 'Correto. É a redação do art. 157, caput, do CPP, em consonância com o art. 5º, LVI, da CF.'),
    q(T34, PR, 'E', 'As provas derivadas das ilícitas são sempre admissíveis no processo penal, pois apenas a prova originalmente ilícita deve ser desentranhada.', 'Errado. O art. 157, § 1º, do CPP também torna inadmissíveis as provas derivadas, salvo quando não evidenciado o nexo de causalidade ou quando puderem ser obtidas por fonte independente.'),
    q(T34, PR, 'C', 'A prova derivada da ilícita é admissível quando não evidenciado o nexo de causalidade entre umas e outras ou quando puder ser obtida por uma fonte independente das primeiras.', 'Correto. São as exceções previstas no art. 157, § 1º, do CPP à teoria dos frutos da árvore envenenada.'),
    q(T34, PR, 'E', 'Preclusa a decisão de desentranhamento da prova declarada inadmissível, ela deverá permanecer arquivada em cartório, indefinidamente, à disposição das partes.', 'Errado. Pelo art. 157, § 3º, do CPP, preclusa a decisão, a prova será inutilizada por decisão judicial, facultado às partes acompanhar o incidente.'),
    q(T34, PR, 'C', 'É lícita a prova consistente em gravação ambiental de conversa realizada por um dos interlocutores sem o conhecimento do outro, ausente causa legal específica de sigilo.', 'Correto. O STF firmou esse entendimento em repercussão geral (RE 583.937, Tema 237).'),
    q(T34, PR, 'E', 'Durante abordagem em rodovia federal, é lícita a prova obtida pelo policial que, sem consentimento do condutor nem autorização judicial, acessa as conversas de aplicativo de mensagens no celular apreendido em flagrante.', 'Errado. A jurisprudência do STJ considera ilícita a prova obtida pelo acesso a dados e conversas de celular sem autorização judicial ou consentimento válido, por violação da intimidade (art. 5º, X e XII, da CF).'),
    q(T34, PR, 'C', 'A doutrina e a jurisprudência admitem a utilização de prova obtida por meio ilícito quando ela for o único meio de demonstrar a inocência do réu.', 'Correto. Trata-se da prova ilícita pro reo, admitida com base no princípio da proporcionalidade e na prevalência do direito de liberdade.'),
    q(T34, PR, 'E', 'É válida a busca pessoal fundada exclusivamente na impressão subjetiva do policial de que o abordado apresentava atitude suspeita ou nervosismo, sendo lícitas as provas dela decorrentes.', 'Errado. O STJ exige fundada suspeita baseada em elementos objetivos (art. 244 do CPP); impressões subjetivas, como nervosismo ou atitude suspeita, não bastam, tornando ilícita a prova obtida.'),
    q(T34, PR, 'C', 'A entrada forçada em domicílio sem mandado judicial é lícita, mesmo à noite, quando amparada em fundadas razões, devidamente justificadas a posteriori, que indiquem situação de flagrante delito no interior da casa.', 'Correto. É a tese fixada pelo STF no RE 603.616 (Tema 280), com fundamento no art. 5º, XI, da CF.'),
    q(T34, PR, 'E', 'A denúncia anônima, por si só, autoriza o ingresso forçado de policiais em domicílio sem mandado judicial, sendo lícitas as provas encontradas.', 'Errado. A jurisprudência exige fundadas razões, apoiadas em elementos concretos, para o ingresso sem mandado; a denúncia anônima isolada não basta (Tema 280 do STF).'),

    /* 3.5 Meios de prova */
    q(T35, PR, 'C', 'Quando a infração deixar vestígios, será indispensável o exame de corpo de delito, direto ou indireto, não podendo supri-lo a confissão do acusado.', 'Correto. É a literalidade do art. 158, caput, do CPP.'),
    q(T35, PR, 'E', 'Desaparecidos os vestígios da infração, a ausência do exame de corpo de delito não pode ser suprida por qualquer outro meio, impondo-se a absolvição do réu.', 'Errado. O art. 167 do CPP prevê que, não sendo possível o exame por terem desaparecido os vestígios, a prova testemunhal poderá suprir-lhe a falta.'),
    q(T35, PR, 'C', 'O silêncio do acusado no interrogatório não importará confissão e não poderá ser interpretado em prejuízo da defesa.', 'Correto. É o que dispõe o art. 186, parágrafo único, do CPP, em harmonia com o art. 5º, LXIII, da CF.'),
    q(T35, PR, 'E', 'A confissão do acusado é indivisível e irretratável.', 'Errado. Pelo art. 200 do CPP, a confissão é divisível e retratável, sem prejuízo do livre convencimento do juiz, fundado no exame das provas em conjunto.'),
    q(T35, PR, 'C', 'O ascendente, o descendente, o cônjuge e o irmão do acusado podem recusar-se a depor como testemunhas, salvo quando não for possível, por outro modo, obter-se ou integrar-se a prova do fato e de suas circunstâncias.', 'Correto. É a regra do art. 206 do CPP.'),
    q(T35, PR, 'E', 'Os menores de 14 anos, quando ouvidos como testemunhas, prestam o compromisso de dizer a verdade, sujeitando-se ao crime de falso testemunho.', 'Errado. O art. 208 do CPP determina que não se deferirá o compromisso aos menores de 14 anos, que são ouvidos como informantes.'),
    q(T35, PR, 'C', 'Na audiência, as perguntas às testemunhas são formuladas pelas partes diretamente, não admitindo o juiz aquelas que puderem induzir a resposta, não tiverem relação com a causa ou importarem repetição de outra já respondida.', 'Correto. É a disciplina do art. 212 do CPP.'),
    q(T35, PR, 'E', 'O advogado que tomou conhecimento de fatos em razão da profissão é obrigado a depor sobre eles como testemunha, ainda que não desobrigado pelo cliente.', 'Errado. O art. 207 do CPP proíbe de depor as pessoas que, em razão de função, ministério, ofício ou profissão, devam guardar segredo, salvo se, desobrigadas pela parte interessada, quiserem dar o seu testemunho.'),
    q(T35, PR, 'C', 'O exame de corpo de delito e outras perícias serão realizados por perito oficial, portador de diploma de curso superior; na falta deste, o exame será realizado por duas pessoas idôneas, portadoras de diploma de curso superior, preferencialmente na área específica.', 'Correto. É o que dispõe o art. 159, caput e § 1º, do CPP.'),
    q(T35, PR, 'E', 'Para o STJ, as formalidades do reconhecimento de pessoas previstas no art. 226 do CPP são meras recomendações, de modo que sua inobservância não afeta a validade do ato nem o seu uso para fundamentar condenação.', 'Errado. Desde o HC 598.886 (2020), o STJ entende que o procedimento do art. 226 do CPP constitui garantia mínima do suspeito, e o reconhecimento feito em desconformidade não pode servir de lastro a eventual condenação.'),

    /* 3.6 Busca e apreensão */
    q(T36, PR, 'C', 'A busca pessoal independerá de mandado no caso de prisão, quando houver fundada suspeita de que a pessoa esteja na posse de arma proibida ou de objetos ou papéis que constituam corpo de delito, ou quando a medida for determinada no curso de busca domiciliar.', 'Correto. É a literalidade do art. 244 do CPP.'),
    q(T36, PR, 'E', 'A busca domiciliar pode ser executada durante a noite, desde que haja mandado judicial, independentemente do consentimento do morador.', 'Errado. Pelo art. 5º, XI, da CF e pelo art. 245 do CPP, a busca domiciliar por determinação judicial é executada de dia, salvo se o morador consentir que se realize à noite.'),
    q(T36, PR, 'C', 'A busca em mulher será feita por outra mulher, se não importar retardamento ou prejuízo da diligência.', 'Correto. É a regra do art. 249 do CPP.'),
    q(T36, PR, 'E', 'A busca pessoal em mulher abordada em rodovia federal só pode ser realizada por policial do sexo feminino, sob pena de nulidade, ainda que a espera cause retardamento ou prejuízo à diligência.', 'Errado. O art. 249 do CPP excepciona a regra quando a busca por outra mulher importar retardamento ou prejuízo da diligência.'),
    q(T36, PR, 'C', 'Segundo a jurisprudência do STJ, a busca em veículo automotor equipara-se à busca pessoal, dispensando mandado judicial quando houver fundada suspeita, salvo quando o veículo for utilizado como habitação.', 'Correto. O veículo, em regra, não se confunde com domicílio, aplicando-se o art. 244 do CPP; a proteção domiciliar alcança veículos destinados à moradia, como trailers e motor-homes.'),
    q(T36, PR, 'E', 'O delegado de polícia pode expedir mandado de busca e apreensão domiciliar em situações de urgência, submetendo-o posteriormente ao juiz.', 'Errado. A busca domiciliar sem consentimento, fora das hipóteses de flagrante, desastre ou socorro, exige determinação judicial (art. 5º, XI, da CF), em regime de reserva de jurisdição.'),
    q(T36, PR, 'C', 'Não será permitida a apreensão de documento em poder do defensor do acusado, salvo quando constituir elemento do corpo de delito.', 'Correto. É o que dispõe o art. 243, § 2º, do CPP.'),
    q(T36, PR, 'E', 'Para fins de busca domiciliar, o conceito de casa não abrange o compartimento não aberto ao público onde alguém exerce profissão ou atividade.', 'Errado. O art. 246 do CPP estende as regras da busca domiciliar ao compartimento não aberto ao público onde alguém exerce profissão ou atividade.'),
    q(T36, PR, 'C', 'Na busca domiciliar, os executores, antes de penetrarem na casa, mostrarão e lerão o mandado ao morador, intimando-o a abrir a porta; em caso de desobediência, será arrombada a porta e forçada a entrada.', 'Correto. É a disciplina do art. 245, caput e § 2º, do CPP.'),
    q(T36, PR, 'E', 'O mandado de busca domiciliar pode ser genérico, dispensando a indicação da casa e do nome do proprietário ou morador, bastando a menção ao crime investigado.', 'Errado. O art. 243, I e II, do CPP exige que o mandado indique, o mais precisamente possível, a casa e o nome do proprietário ou morador, e mencione o motivo e os fins da diligência.'),

    /* 4.1 Prisão: conceito, formalidades, espécies e mandado */
    q(T41, PS, 'C', 'Ninguém poderá ser preso senão em flagrante delito ou por ordem escrita e fundamentada da autoridade judiciária competente, em decorrência de prisão cautelar ou em virtude de condenação criminal transitada em julgado.', 'Correto. É a redação do art. 283, caput, do CPP, dada pelo Pacote Anticrime.'),
    q(T41, PS, 'E', 'Em situações de urgência, a autoridade policial pode decretar a prisão preventiva do investigado, comunicando o fato ao juiz em até 24 horas.', 'Errado. A prisão preventiva é decretada exclusivamente pelo juiz (art. 311 do CPP), mediante requerimento do MP, do querelante ou do assistente, ou representação da autoridade policial.'),
    q(T41, PS, 'C', 'Qualquer agente policial poderá efetuar a prisão determinada em mandado registrado no banco de dados do CNJ, ainda que fora da competência territorial do juiz que o expediu.', 'Correto. É o que dispõe o art. 289-A, § 1º, do CPP.'),
    q(T41, PS, 'E', 'Após o Pacote Anticrime, o juiz pode decretar a prisão preventiva de ofício no curso da ação penal, sendo vedada a decretação de ofício apenas na fase de investigação.', 'Errado. O art. 311 do CPP, com a redação do Pacote Anticrime, eliminou a decretação de ofício em qualquer fase: a preventiva depende de requerimento ou representação.'),
    q(T41, PS, 'C', 'Se a infração for inafiançável, a falta de exibição do mandado não obstará a prisão, e o preso, nesse caso, será imediatamente apresentado ao juiz que tiver expedido o mandado, para a realização de audiência de custódia.', 'Correto. É a redação do art. 287 do CPP.'),
    q(T41, PS, 'E', 'Segundo a Súmula Vinculante 11, o uso de algemas é livre em qualquer prisão, dispensando justificativa, por se tratar de medida inerente à atividade policial.', 'Errado. A SV 11 só admite algemas em caso de resistência, fundado receio de fuga ou perigo à integridade física própria ou alheia, justificada a excepcionalidade por escrito.'),
    q(T41, PS, 'C', 'Não será permitido o emprego de força na prisão, salvo a indispensável no caso de resistência ou de tentativa de fuga do preso.', 'Correto. É a regra do art. 284 do CPP.'),
    q(T41, PS, 'E', 'A prisão temporária pode ser decretada tanto no curso do inquérito policial quanto no curso da ação penal, para assegurar a instrução criminal.', 'Errado. A prisão temporária (Lei 7.960/1989) destina-se exclusivamente à fase investigativa, quando imprescindível para as investigações do inquérito policial.'),
    q(T41, PS, 'C', 'O preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial.', 'Correto. É a garantia do art. 5º, LXIV, da CF.'),
    q(T41, PS, 'E', 'Nos crimes comuns, a prisão temporária tem prazo de dez dias, prorrogável por igual período em caso de extrema e comprovada necessidade.', 'Errado. O prazo é de cinco dias, prorrogável por igual período (art. 2º da Lei 7.960/1989); para hediondos e equiparados, é de 30 dias, prorrogável por igual período (art. 2º, § 4º, da Lei 8.072/1990).'),

    /* 4.2 Prisão em flagrante */
    q(T42, PS, 'C', 'Qualquer do povo poderá e as autoridades policiais e seus agentes deverão prender quem quer que seja encontrado em flagrante delito.', 'Correto. É a redação do art. 301 do CPP: flagrante facultativo para o particular e obrigatório para as autoridades e seus agentes.'),
    q(T42, PS, 'E', 'Para o policial rodoviário federal, a prisão em flagrante é ato facultativo, que pode deixar de ser realizado por critérios de conveniência operacional.', 'Errado. Para as autoridades policiais e seus agentes, o flagrante é obrigatório (art. 301 do CPP).'),
    q(T42, PS, 'C', 'Considera-se em flagrante delito quem é perseguido, logo após, pela autoridade, pelo ofendido ou por qualquer pessoa, em situação que faça presumir ser autor da infração.', 'Correto. É o flagrante impróprio ou imperfeito, previsto no art. 302, III, do CPP.'),
    q(T42, PS, 'E', 'Denomina-se flagrante presumido ou ficto a situação de quem é surpreendido no momento em que está cometendo a infração penal.', 'Errado. Essa situação caracteriza o flagrante próprio (art. 302, I, do CPP); o flagrante presumido é o de quem é encontrado, logo depois, com instrumentos, armas, objetos ou papéis que façam presumir ser ele o autor (art. 302, IV).'),
    q(T42, PS, 'C', 'Policiais rodoviários federais que encontram cocaína oculta em caminhão transportado pelo motorista podem prendê-lo em flagrante, pois, nas infrações permanentes, entende-se o agente em flagrante enquanto não cessar a permanência.', 'Correto. É a regra do art. 303 do CPP; o transporte de drogas é conduta permanente.'),
    q(T42, PS, 'E', 'É válida a prisão em flagrante quando a preparação do flagrante pela polícia torna impossível a consumação do crime.', 'Errado. Segundo a Súmula 145 do STF, não há crime quando a preparação do flagrante pela polícia torna impossível a sua consumação.'),
    q(T42, PS, 'C', 'É válido o flagrante esperado, no qual os policiais, informados da futura prática do crime, aguardam o momento de sua execução para efetuar a prisão, sem induzir o agente.', 'Correto. No flagrante esperado não há provocação do agente, diferentemente do flagrante preparado (Súmula 145 do STF).'),
    q(T42, PS, 'E', 'O auto de prisão em flagrante deve ser encaminhado ao juiz competente em até 48 horas após a realização da prisão.', 'Errado. O art. 306, § 1º, do CPP fixa o prazo de 24 horas; no mesmo prazo, deve ser entregue a nota de culpa ao preso (§ 2º).'),
    q(T42, PS, 'C', 'Ao condutor de veículo envolvido em acidente de trânsito de que resulte vítima não se imporá a prisão em flagrante, nem se exigirá fiança, se prestar pronto e integral socorro àquela.', 'Correto. É a regra do art. 301 do CTB.'),
    q(T42, PS, 'E', 'A falta de testemunhas da infração impede a lavratura do auto de prisão em flagrante.', 'Errado. Pelo art. 304, § 2º, do CPP, a falta de testemunhas não impede o auto, mas com o condutor deverão assiná-lo pelo menos duas pessoas que tenham testemunhado a apresentação do preso à autoridade.'),

    /* 5 Identificação criminal */
    q(T5, ID, 'C', 'Segundo a Constituição Federal, o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei.', 'Correto. É a garantia do art. 5º, LVIII, da CF, regulamentada pela Lei 12.037/2009.'),
    q(T5, ID, 'E', 'A pessoa civilmente identificada jamais pode ser submetida a identificação criminal, por expressa vedação constitucional.', 'Errado. A CF admite exceções previstas em lei (art. 5º, LVIII), e o art. 3º da Lei 12.037/2009 enumera hipóteses de identificação criminal mesmo com apresentação de documento.'),
    q(T5, ID, 'C', 'Embora apresentado documento de identificação, poderá ocorrer identificação criminal quando o documento apresentar rasura ou tiver indício de falsificação.', 'Correto. É a hipótese do art. 3º, I, da Lei 12.037/2009.'),
    q(T5, ID, 'E', 'Quando a identificação criminal for essencial às investigações, basta despacho fundamentado do delegado de polícia para realizá-la, dispensando-se manifestação judicial.', 'Errado. Na hipótese do art. 3º, IV, da Lei 12.037/2009, exige-se despacho da autoridade judiciária competente, de ofício ou mediante representação da autoridade policial, do MP ou da defesa.'),
    q(T5, ID, 'C', 'Indiciado abordado em rodovia federal que porta documentos de identidade distintos, com informações conflitantes entre si, pode ser submetido a identificação criminal.', 'Correto. É a hipótese do art. 3º, III, da Lei 12.037/2009.'),
    q(T5, ID, 'E', 'A carteira de identificação funcional não é documento apto a atestar a identificação civil para fins da Lei 12.037/2009.', 'Errado. O art. 2º, V, da Lei 12.037/2009 inclui a carteira de identificação funcional entre os documentos que atestam a identificação civil.'),
    q(T5, ID, 'C', 'A identificação criminal incluirá o processo datiloscópico e o fotográfico, que serão juntados aos autos da comunicação da prisão em flagrante, do inquérito policial ou de outra forma de investigação.', 'Correto. É o que dispõe o art. 5º, caput, da Lei 12.037/2009.'),
    q(T5, ID, 'E', 'É permitido mencionar a identificação criminal do indiciado em atestados de antecedentes, ainda antes do trânsito em julgado da sentença condenatória.', 'Errado. O art. 6º da Lei 12.037/2009 veda essa menção em atestados de antecedentes ou em informações não destinadas ao juízo criminal antes do trânsito em julgado.'),
    q(T5, ID, 'C', 'As cópias dos documentos apresentados pelo indiciado deverão ser juntadas aos autos do inquérito, ainda que consideradas insuficientes para identificá-lo.', 'Correto. É a regra do art. 3º, parágrafo único, da Lei 12.037/2009.'),
    q(T5, ID, 'E', 'A coleta de material biológico para obtenção de perfil genético pode integrar a identificação criminal em qualquer das hipóteses do art. 3º da Lei 12.037/2009, a critério da autoridade policial.', 'Errado. Segundo o art. 5º, parágrafo único, da Lei 12.037/2009, a coleta de material biológico só é admitida na hipótese do inciso IV do art. 3º, que depende de decisão judicial.'),

    /* 6 Diligências investigatórias */
    q(T6, ID, 'C', 'Logo que tiver conhecimento da prática da infração penal, a autoridade policial deverá ouvir o ofendido e colher todas as provas que servirem para o esclarecimento do fato e suas circunstâncias.', 'Correto. São diligências previstas no art. 6º, III e IV, do CPP.'),
    q(T6, ID, 'E', 'Como regra, a autoridade policial deve apreender os objetos relacionados ao fato antes mesmo de sua liberação pelos peritos criminais, para evitar extravio.', 'Errado. O art. 6º, II, do CPP determina a apreensão dos objetos que tiverem relação com o fato após liberados pelos peritos criminais.'),
    q(T6, ID, 'C', 'Entre as diligências do art. 6º do CPP, inclui-se colher informações sobre a existência de filhos, suas idades e se possuem alguma deficiência, bem como o nome e o contato de eventual responsável por seus cuidados, indicado pela pessoa presa.', 'Correto. É a previsão do art. 6º, X, do CPP, incluída pelo Marco Legal da Primeira Infância.'),
    q(T6, ID, 'E', 'A autoridade policial pode deixar de realizar diligência requisitada pelo juiz ou pelo Ministério Público se discordar de sua conveniência para a investigação.', 'Errado. O art. 13, II, do CPP incumbe à autoridade policial realizar as diligências requisitadas pelo juiz ou pelo MP; requisição tem natureza de ordem legal.'),
    q(T6, ID, 'C', 'Para verificar a possibilidade de o crime ter sido praticado de determinado modo, a autoridade policial poderá proceder à reprodução simulada dos fatos, desde que esta não contrarie a moralidade ou a ordem pública.', 'Correto. É o que dispõe o art. 7º do CPP.'),
    q(T6, ID, 'E', 'O investigado é obrigado a participar da reprodução simulada dos fatos, podendo ser conduzido coercitivamente caso se recuse.', 'Errado. Em razão do direito de não produzir prova contra si mesmo (nemo tenetur se detegere), o investigado não é obrigado a participar da reprodução simulada.'),
    q(T6, ID, 'C', 'Incumbe à autoridade policial cumprir os mandados de prisão expedidos pelas autoridades judiciárias e representar acerca da prisão preventiva.', 'Correto. São atribuições previstas no art. 13, III e IV, do CPP.'),
    q(T6, ID, 'E', 'O requerimento de diligência formulado pelo ofendido ou pelo indiciado vincula a autoridade policial, que deverá realizá-la obrigatoriamente.', 'Errado. Segundo o art. 14 do CPP, a diligência requerida pelo ofendido ou pelo indiciado será realizada, ou não, a juízo da autoridade.'),
    q(T6, ID, 'C', 'Nos crimes relacionados ao tráfico de pessoas, se não houver manifestação judicial em 12 horas sobre o pedido de disponibilização de sinais para localização da vítima ou dos suspeitos, a autoridade competente requisitará diretamente às empresas de telecomunicações, com imediata comunicação ao juiz.', 'Correto. É a regra do art. 13-B, § 4º, do CPP.'),
    q(T6, ID, 'E', 'O termo de oitiva do indiciado na fase policial dispensa a assinatura de testemunhas, bastando a assinatura da autoridade e do escrivão.', 'Errado. O art. 6º, V, do CPP exige que o termo seja assinado por duas testemunhas que tenham ouvido a sua leitura.')
  ]);
})();
